styles:
/* CSS CHÍNH: Nền đen, Tiêu đề trắng, Body trắng, Font Roboto Condensed, KHÔNG KHUNG */
        body {
            font-family: 'Roboto Condensed', sans-serif;
            line-height: 1.6;
            color: #FFFFFF;
            margin: 0;
            padding: 0;
            background-color: #000000;
        }
        .container {
            max-width: 900px;
            margin: 20px auto;
            padding: 20px 30px;
        }
        h1, h2, h3, h4 {
            color: #FFFFFF;
            font-weight: 700;
            text-transform: uppercase;
            font-family: 'Roboto Condensed' !important;
        }
        h1 {
            font-size: 2.5em;
            border-bottom: 3px solid #330000;
            padding-bottom: 15px;
            margin-bottom: 25px;
            text-align: center;
            letter-spacing: 1px;
        }
        h2 {
            font-size: 1.8em;
            margin-top: 30px;
            border-left: 5px solid #cc0000;
            padding-left: 10px;
        }
        h3 {
             font-size: 1.3em;
             margin-top: 20px;
             color: #ff3333;
        }
        h4 {
             font-size: 1.1em;
             margin-top: 15px;
             color: #ffcc00;
        }
        p {
            margin-bottom: 15px;
            color: #FFFFFF;
        }
        .highlight {
            font-weight: bold;
            color: #FFFFFF;
        }
        .note {
            background-color: #331a1a;
            padding: 15px;
            border-left: 5px solid #ffcc00;
            margin: 20px 0;
            border-radius: 5px;
            color: #f0f0f0;
        }
        a {
            color: #ff3333;
            text-decoration: none;
        }
        a:hover {
            text-decoration: underline;
        }
        ul {
            padding-left: 25px;
            margin-bottom: 20px;
        }
        li {
            margin-bottom: 10px;
        }
        code {
            background-color: #331a1a;
            padding: 2px 4px;
            border-radius: 3px;
            color: #ffcc00;
        }

        /* ── TOOL INFO BOX với label "TIÊU ĐIỂM" góc trên phải ── */
        .tool-info {
            background-color: #141400;
            border: 1px solid #7a6600;
            border-right: 4px solid #ffcc00;
            padding: 14px 18px;
            margin: 16px 0 20px 0;
            border-radius: 4px;
            
            position: relative;
        }
        .tool-info::after {
            content: "TIÊU ĐIỂM";
            position: absolute;
            top: -10px;
            right: 10px;
            background: #ffcc00;
            color: #000000;
            font-size: 0.7rem;
            padding: 2px 8px;
            font-weight: 700;
            font-family: 'Roboto Condensed', sans-serif;
            letter-spacing: 0.5px;
        }
        .tool-info p {
            margin: 0;
            padding: 2px 0;
            line-height: 1.5;
            color: #FFFFFF;
            font-size: 1em;
        }
        .tool-info strong {
            color: #ffcc00;
            font-weight: 700;
        }

        /* ── XEM THÊM BOX — yellow style ── */
        .xem-them {
            display: block;
            box-sizing: border-box;
            width: 100%;
            background-color: #1a1200;
            border-top: 1px solid #7a5500;
            border-right: 1px solid #7a5500;
            border-bottom: 1px solid #7a5500;
            border-left: 4px solid #ffaa33;
            border-radius: 4px;
            padding: 11px 16px;
            margin: 20px 0 24px 0;
            font-family: 'Roboto Condensed', sans-serif;
            font-size: 0.95em;
            font-weight: 700;
            color: #ffaa33;
            letter-spacing: 0.4px;
            text-transform: uppercase;
            line-height: 1.5;
        }
        .xem-them a {
            color: #ffcc77;
            text-decoration: none;
            font-weight: 400;
            text-transform: none;
            letter-spacing: 0;
        }
        .xem-them a:hover {
            color: #ffe8aa;
            text-decoration: underline;
        }
